  pageTopSpenders: {
    auth: { kind: "any", scope: "page" },
    tags: ["fans"],
    summary: "Top spenders for one page from the fan-earnings projection (Stage 32 board)",
    params: pageParamsSchema,
    querystring: external_exports.object({
      // 'lifetime' or a month window ('2026-06') — the projection's window values.
      window: external_exports.string().regex(/^(lifetime|\d{4}-\d{2})$/).default("lifetime"),
      limit: external_exports.coerce.number().int().min(1).max(1e3).default(150)
    }),
    response: {
      200: external_exports.object({
        window: external_exports.string(),
        /** Freshest observed_at in the window (null = projection empty for this page). */
        builtAt: external_exports.string().nullable(),
        /** Spenders with gross > 0 in this window (entries may be a bounded subset). */
        fanCount: external_exports.number().int().nonnegative(),
        /** W8.1 (A12/A20): why the projection is (or is not) being fed — a
         * `builtAt: null` response is no longer ambiguous between "no
         * spenders" and "stream not ramped for this page". Additive. */
        source: external_exports.object({
          streamState: external_exports.enum(["ramped", "flag_off", "not_allowlisted", "unsupported_platform"]),
          /** fan_earnings stream's last successful sync for this page. */
          lastSyncedAt: external_exports.string().nullable(),
          /** null = the page has no fan_earnings sync state row yet. */
          consecutiveFailures: external_exports.number().int().nullable()
        }),
        entries: external_exports.array(external_exports.object({
          platformUserId: external_exports.string(),
          username: external_exports.string().nullable(),
          displayName: external_exports.string().nullable(),
          grossMills: external_exports.number().int().nonnegative(),
          netMills: external_exports.number().int().nullable(),
          currency: external_exports.string(),
          observedAt: external_exports.string(),
          /** First time hydration failed to find this account on the platform
           * (fans.deleted_detected_at); null = the fan is alive. Cleared server
           * side as soon as any sync sees a name again (fans.ts:116-136).
           * Optional so a client vendored against an older kernel still
           * validates the response. */
          deletedAt: external_exports.string().nullable().optional()
        }))
      }),
      401: errorResponseSchema,
      403: errorResponseSchema,
      404: errorResponseSchema
    }
  },
